PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    MotorOn : BOOL := FALSE;
    EmergencyTimer : TON;
END_VAR

EmergencyTimer(IN := NOT(EStop), PT := T#0s);

IF EStop = FALSE THEN
    Motor := FALSE;
    MotorOn := FALSE;
ELSIF Start AND NOT(MotorOn) THEN
    Motor := TRUE;
    MotorOn := TRUE;
ELSIF Stop OR EmergencyTimer.Q THEN
    Motor := FALSE;
    MotorOn := FALSE;
END_IF;

Motor := Motor AND NOT(EmergencyTimer.Q);
END_PROGRAM

