PROGRAM motor_interlock
VAR_INPUT
    Start : BOOL;
    Stop : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Motor : BOOL;
END_VAR

VAR
    motor_latched : BOOL := FALSE;
    e_stop_timer : TON;
END_VAR

// Check if EStop is activated
IF NOT EStop THEN
    // Emergency stop activated, de-energize motor and clear latch
    Motor := FALSE;
    motor_latched := FALSE;
    e_stop_timer(IN := TRUE, PT := T#0s);
ELSE
    // EStop not activated, check for Start/Stop conditions
    IF Start AND NOT Stop AND NOT motor_latched THEN
        // Start button pressed and no Stop, latch motor on
        motor_latched := TRUE;
    ELSIF Stop OR e_stop_timer.Q THEN
        // Stop button pressed or EStop timer timed out, clear latch
        motor_latched := FALSE;
    END_IF;

    // Assign motor state based on latch
    Motor := motor_latched;
END_IF;
END_PROGRAM

