PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    last_pump_state : BOOL := FALSE;
END_VAR

IF Level >= 90 THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= 10 THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := last_pump_state;
    ValveOut := FALSE;
END_IF;

last_pump_state := PumpIn;
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    prev_pump_state : BOOL := FALSE;
    prev_valve_state : BOOL := FALSE;
    hysteresis_low_limit : INT := 10;
    hysteresis_high_limit : INT := 90;
END_VAR

// Check if the level is at or above the high limit
IF Level >= hysteresis_high_limit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= hysteresis_low_limit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Ensure the inlet pump does not run while the level is at or above the high limit
IF Level >= hysteresis_high_limit AND NOT prev_pump_state THEN
    PumpIn := FALSE;
END_IF;

prev_pump_state := PumpIn;
prev_valve_state := ValveOut;
END_PROGRAM

