PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    PumpInTimer : TON;
    ValveOutTimer : TON;
END_VAR

// Check if the level is at or above the high limit (90%)
IF Level >= 90 THEN
    // Turn off the inlet pump
    PumpIn := FALSE;

    // Open the outlet valve to prevent overflow
    ValveOut := TRUE;

    // Reset the timers
    PumpInTimer(IN := FALSE);
    ValveOutTimer(IN := FALSE);
ELSE
    // Check if the level is at or below the low limit (10%)
    IF Level <= 10 THEN
        // Turn on the inlet pump
        PumpIn := TRUE;

        // Close the outlet valve
        ValveOut := FALSE;

        // Reset the timers
        PumpInTimer(IN := FALSE);
        ValveOutTimer(IN := FALSE);
    ELSE
        // Maintain the current state
        PumpIn := PumpInTimer.Q;
        ValveOut := ValveOutTimer.Q;

        // Reset the timers
        PumpInTimer(IN := FALSE);
        ValveOutTimer(IN := FALSE);
    END_IF;
END_IF;

// Update the timers
PumpInTimer(IN := TRUE, PT := T#3s);
ValveOutTimer(IN := TRUE, PT := T#3s);
END_PROGRAM

PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    prev_pump_state : BOOL := FALSE;
    prev_valve_state : BOOL := FALSE;
    pump_timer : TON;
    valve_timer : TON;
END_VAR

// Check if the pump state needs to change
IF NOT prev_pump_state AND Level <= 10 THEN
    PumpIn := TRUE;
    pump_timer(IN := TRUE, PT := T#2s);
ELSIF prev_pump_state AND Level >= 90 THEN
    PumpIn := FALSE;
    prev_pump_state := FALSE;
ELSIF prev_pump_state AND NOT pump_timer.Q THEN
    PumpIn := FALSE;
    prev_pump_state := FALSE;
END_IF;

// Check if the valve state needs to change
IF NOT prev_valve_state AND Level >= 90 THEN
    ValveOut := TRUE;
    valve_timer(IN := TRUE, PT := T#2s);
ELSIF prev_valve_state AND Level <= 10 THEN
    ValveOut := FALSE;
    prev_valve_state := FALSE;
ELSIF prev_valve_state AND NOT valve_timer.Q THEN
    ValveOut := FALSE;
    prev_valve_state := FALSE;
END_IF;

prev_pump_state := PumpIn;
prev_valve_state := ValveOut;
END_PROGRAM

PROGRAM tank_level
