VAR
    prev_PumpIn : BOOL := FALSE;
    prev_ValveOut : BOOL := FALSE;
    LimitLow : INT := 10;
    LimitHigh : INT := 90;
    T_Hyst : TON;
END_VAR

T_Hyst(IN := NOT(prev_PumpIn OR prev_ValveOut) AND (Level <= LimitLow OR Level >= LimitHigh), PT := T#1s);

IF T_Hyst.Q THEN
    PumpIn := Level <= LimitLow;
    ValveOut := Level >= LimitHigh;
ELSE
    PumpIn := prev_PumpIn;
    ValveOut := prev_ValveOut;
END_IF;

prev_PumpIn := PumpIn;
prev_ValveOut := ValveOut;
END_PROGRAM

