PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR

VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR

VAR
    DoorA_Latch : BOOL := FALSE;
    DoorB_Latch : BOOL := FALSE;
    DoorA_Timer : TON;
    DoorB_Timer : TON;
END_VAR

// Priority rule for Door A
IF OpenA_Cmd AND NOT OpenB_Cmd THEN
    DoorA_Latch := TRUE;
    DoorB_Latch := FALSE;
    DoorA_Timer(IN := TRUE, PT := T#0s);
    DoorB_Timer(IN := FALSE, PT := T#0s);
ELSIF NOT OpenA_Cmd AND OpenB_Cmd THEN
    DoorA_Latch := FALSE;
    DoorB_Latch := TRUE;
    DoorA_Timer(IN := FALSE, PT := T#0s);
    DoorB_Timer(IN := TRUE, PT := T#0s);
ELSE
    DoorA_Latch := FALSE;
    DoorB_Latch := FALSE;
    DoorA_Timer(IN := FALSE, PT := T#0s);
    DoorB_Timer(IN := FALSE, PT := T#0s);
END_IF;

// Apply latching and timing rules
IF DoorA_Latch AND NOT DoorB_Latch THEN
    DoorA := TRUE;
    DoorB := FALSE;
ELSIF DoorB_Latch AND NOT DoorA_Latch THEN
    DoorA := FALSE;
    DoorB := TRUE;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
END_IF;

END_PROGRAM

