    ELSE
        DoorB_Latch := FALSE;
    END_IF;
ELSIF DoorB_Timer.Q THEN
    DoorB_Latch := FALSE;
END_IF;

IF DoorA_Latch THEN
    DoorA := TRUE;
    DoorB := FALSE;
ELSIF DoorB_Latch THEN
    DoorA := FALSE;
    DoorB := TRUE;
END_IF;

