END_VAR

// Turn on heater if demand and enabled, off otherwise
HeaterControl := HeatRequest AND Enable;

// Override: turn off heater if over temperature
IF OverTemp THEN
    HeaterControl := FALSE;
END_IF;

// Assign the controlled state to the heater output
Heater := HeaterControl;
