PROGRAM pump_ctrl
VAR_INPUT
    Demand : BOOL;
    LowLevel : BOOL;
END_VAR

VAR_OUTPUT
    Pump : BOOL;
END_VAR

VAR
    SafetyTimer : TON;
END_VAR

// Check if the supply level is too low
IF LowLevel THEN
    // If the supply level is too low, stop the pump immediately
    Pump := FALSE;
    // Reset the safety timer
    SafetyTimer(IN := FALSE);
ELSE
    // If the supply level is sufficient, check the demand
    IF Demand THEN
        // If there is a demand and the supply level is okay, turn on the pump
        Pump := TRUE;
        // Start or reset the safety timer
        SafetyTimer(IN := TRUE, PT := T#5s);
    ELSE
        // If there is no demand, turn off the pump
        Pump := FALSE;
        // Reset the safety timer
        SafetyTimer(IN := FALSE);
    END_IF;

    // Check if the safety timer has timed out
    IF NOT SafetyTimer.Q THEN
        // If the safety timer has timed out, it means the pump has been running for more than the safety period
        // This should never happen under normal conditions, but we handle it as a safety measure
        Pump := FALSE;
    END_IF;
END_IF;
END_PROGRAM

