PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT := 0;
    GreenTimer : TON;
    YellowTimer : TON;
    AllRedTimer : TON;
END_VAR;

CASE State OF
    0:
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        GreenTimer(IN := TRUE, PT := T#2s);
        IF GreenTimer.Q THEN
            State := 1;
        END_IF;
    1:
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        YellowTimer(IN := TRUE, PT := T#1s);
        IF YellowTimer.Q THEN
            State := 2;
        END_IF;
    2:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        AllRedTimer(IN := TRUE, PT := T#1s);
        IF AllRedTimer.Q THEN
            State := 3;
        END_IF;
    3:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := FALSE;
        GreenTimer(IN := TRUE, PT := T#2s);
        IF GreenTimer.Q THEN
            State := 4;
        END_IF;
    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := FALSE;
        YellowTimer(IN := TRUE, PT := T#1s);
        IF YellowTimer.Q THEN
            State := 5;
        END_IF;
    5:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        AllRedTimer(IN := TRUE, PT := T#1s);
        IF AllRedTimer.Q THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM intersection
VAR
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    State : INT;
    T_Green, T_Yellow, T_AllRed : TON;
END_VAR;

T_Green(IN := State = 0 OR State = 3, PT := T#2s);
T_Yellow(IN := State = 1 OR State = 4, PT := T#1s);
T_AllRed(IN := State = 2 OR State = 5, PT := T#1s);

CASE State OF
    0:
        NS_G := TRUE; NS_Y := FALSE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    1:
        NS_G := FALSE; NS_Y := TRUE; NS_R := FALSE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    2:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
    3:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := TRUE; EW_Y := FALSE; EW_R := FALSE;
    4:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := TRUE; EW_R := FALSE;
    5:
        NS_G := FALSE; NS_Y := FALSE; NS_R := TRUE;
        EW_G := FALSE; EW_Y := FALSE; EW_R := TRUE;
END_CASE;

State := CASE State OF
    0: IF T_Green.Q THEN 1 ELSE 0 END_IF;
    1: IF T_Yellow.Q THEN 2 ELSE 1 END_IF;
