            State := 1;
            MoveTimer(IN := TRUE, PT := T#3s);
        END_IF;

    1: // Moving-up
        MotorUp := TRUE;
        MotorDown := FALSE;
        IF MoveTimer.Q OR AtTop THEN
            State := 2;
            MoveTimer(IN := FALSE);
        ELSIF NOT CallUp OR NOT DoorClosed THEN
            State := 0;
            MoveTimer(IN := FALSE);
        END_IF;

    2: // At-top
        MotorUp := FALSE;
        MotorDown := FALSE;
        IF CallDown AND DoorClosed THEN
            State := 3;
            MoveTimer(IN := TRUE, PT := T#3s);
        END_IF;

    3: // Moving-down
        MotorUp := FALSE;
        MotorDown := TRUE;
        IF MoveTimer.Q OR AtBottom THEN
            State := 0;
            MoveTimer(IN := FALSE);
        ELSIF NOT CallDown OR NOT DoorClosed THEN
            State := 2;
            MoveTimer(IN := FALSE);
        END_IF;
END_CASE;

