        ELSE
            Heater := FALSE;
            Agitator := FALSE;
            State := 0;
        END_IF;

    3: // React
        IF NOT EStop AND Level >= LIQ_MIN THEN
            Heater := TRUE;
            Agitator := TRUE;
            IF ReactTimer.Q THEN
                State := 4;
            END_IF;
        ELSE
            Heater := FALSE;
            Agitator := FALSE;
            State := 0;
        END_IF;
        ReactTimer(IN := NOT EStop AND Level >= LIQ_MIN, PT := PT_REACT);

    4: // Drain
        IF NOT EStop THEN
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
        ELSE
            DrainValve := FALSE;
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
FillValve := NOT (EStop OR FillValve AND DrainValve);
DrainValve := NOT (EStop OR FillValve AND DrainValve);

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR

VAR_CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR

VAR
    State : INT := 0;
    Timer : TON;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1: // Fill
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;

        IF Level >= LVL_HIGH THEN
            State := 2;
        END_IF;

    2: // Heat
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

        IF Temp >= TEMP_SET THEN
            State := 3;
        END_IF;

    3: // React
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;

        Timer(IN := TRUE, PT := PT_REACT);
        IF Timer.Q THEN
            State := 4;
        END_IF;

    4: // Drain
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;

        IF Level <= LVL_LOW THEN
            State := 0;
        END_IF;
END_CASE;

// Safety check: never allow fill and drain valves to open simultaneously
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

END_PROGRAM

