VAR
    State : INT := 0;
    FillTimer : TON;
    DrainTimer : TON;
END_VAR

CASE State OF
    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
        IF EStop THEN
            State := 0;
        ELSIF StartCycle AND Level < 90 THEN
            State := 1;
        END_IF;

    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
        IF EStop OR Level >= 90 THEN
            State := 0;
        END_IF;

    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
        IF EStop OR Level <= 10 THEN
            State := 0;
        END_IF;
END_CASE;

