IF Pump AND Valve THEN
    Pump := FALSE;
    Valve := FALSE;
END_IF;

IF Level >= 90 AND NOT Pump THEN
    Pump := TRUE;
END_IF;

IF Level <= 10 AND Valve THEN
    Valve := FALSE;
END_IF;

END_PROGRAM

