PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
END_VAR

// Edge detection for Demand falling edge
PrevDemand := Demand;

IF NOT EStop THEN
    // EStop activated, stop both pumps
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    IF Demand AND NOT PrevDemand THEN
        // Demand just started, alternate Lead
        Lead := 1 - Lead;
    END_IF;

    IF Demand THEN
        // Demand active, run the leading pump
        IF Lead = 0 THEN
            Pump1 := TRUE;
            Pump2 := FALSE;
        ELSE
            Pump1 := FALSE;
            Pump2 := TRUE;
        END_IF;
    ELSE
        // Demand ended, stop both pumps
        Pump1 := FALSE;
        Pump2 := FALSE;
    END_IF;
END_IF;

END_PROGRAM

