            Pump1 := FALSE;
            Pump2 := FALSE;
        END_IF;
END_CASE;

IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
END_IF;

IF NOT PrevDemand AND Demand THEN
    Lead := 1 - Lead; // Toggle lead on demand rise
END_IF;

